const reqMethod = payload.method; if (reqMethod !== 'POST') return; 
const body = payload.body || {}; 
const reqUser = context.user; 
try { 
  // 1. Stok kontrolü
  const urunId = body.urun_id;
  const sip_miktari = Number(body.siparis_miktari);
  const urunRes = await recordManager.getRecord(context.tenantSlug, 'stok_kartlari', urunId);
  if(!urunRes) throw new Error("Ürün bulunamadı");

  const h = typeof urunRes.hashtags === 'string' ? JSON.parse(urunRes.hashtags) : (urunRes.hashtags || []);
  const urunData = urunRes; 
  let mevcut = urunData.mevcut_stok || 0;
  let bloke = urunData.bloke_stok || 0;
  let net_stok = mevcut - bloke;
  if(net_stok < 0) net_stok = 0;

  let sevkiyat_bloke = 0;
  let uretim_hedef = 0;

  if (net_stok >= sip_miktari) {
     sevkiyat_bloke = sip_miktari;
  } else {
     sevkiyat_bloke = net_stok;
     uretim_hedef = sip_miktari - net_stok;
  }

  // 2. Siparişi Kaydet
  body.sevkiyat_bloke_miktar = sevkiyat_bloke;
  body.uretim_hedef_miktar = uretim_hedef;
  body.durum = 'Bekleyen İşler';

  const result = await recordManager.createRecord(context.tenantSlug, 'siparisler', body, reqUser?.id);

  // 3. Stoğu Güncelle (Bloke)
  if (sevkiyat_bloke > 0) {
      await recordManager.updateRecord(context.tenantSlug, 'stok_kartlari', urunId, { bloke_stok: bloke + sevkiyat_bloke }, reqUser?.id);
  }

  // 4. Eğer eksik varsa İş Emri oluştur (Otomatik Görev Atama)
  if (uretim_hedef > 0) {
      await recordManager.createRecord(context.tenantSlug, 'is_emirleri', {
          siparis_id: result.id,
          hedef_miktar: uretim_hedef,
          gerceklesen_miktar: 0,
          fire_miktari: 0,
          durum: 'Bekliyor'
      }, reqUser?.id);
  }

  // 5. WebSocket ile canlı yayınla
  if(typeof publishWS !== 'undefined') publishWS(context.tenantSlug, 'siparis_guncellendi', { action: 'yeni_siparis', siparis_no: body.siparis_no });

  return { respond: true, status: 200, headers: { 'Content-Type': 'application/json' }, body: result }; 
} catch(e) { 
  return { respond: true, status: e.statusCode || 500, headers: { 'Content-Type': 'application/json' }, body: { message: e.message || e, errors: e.data } }; 
}

try {
  const bodyData = payload.method === 'POST' ? payload.body : (payload.query || payload);
  const { action, data } = bodyData || {};
  const reqUser = context.user; 

  if (action === 'islem_baslat') {
     const { is_emri_id } = data;

     // 1. İş Emrini güncelle
     await recordManager.updateRecord(context.tenantSlug, 'is_emirleri', is_emri_id, { durum: 'Üretimde' }, reqUser?.id);

     // 2. İş Emrine ait siparişin durumunu Devam Edenler'e taşı
     const ie = await recordManager.getRecord(context.tenantSlug, 'is_emirleri', is_emri_id);
     if(ie && ie.siparis_id) {
         await recordManager.updateRecord(context.tenantSlug, 'siparisler', ie.siparis_id, { durum: 'Devam Edenler' }, reqUser?.id);
     }

     if(typeof publishWS !== 'undefined') publishWS(context.tenantSlug, 'siparis_guncellendi', { action: 'islem_baslat' });
     return { respond: true, status: 200, body: { success: true } };
  }

  if (action === 'islem_bitir') {
     const { is_emri_id, uretilen, fire, net_sure_sn, gorev_adi } = data;

     // 1. İş Emrini güncelle
     const ie = await recordManager.getRecord(context.tenantSlug, 'is_emirleri', is_emri_id);
     const yeni_gerceklesen = (ie.gerceklesen_miktar || 0) + uretilen;
     const yeni_fire = (ie.fire_miktari || 0) + fire;
     await recordManager.updateRecord(context.tenantSlug, 'is_emirleri', is_emri_id, { durum: 'Tamamlandı', gerceklesen_miktar: yeni_gerceklesen, fire_miktari: yeni_fire }, reqUser?.id);

     // 2. Alt Görev (Log/Süre) kaydı
     if(gorev_adi) {
         await recordManager.createRecord(context.tenantSlug, 'alt_gorevler', { is_emri_id: is_emri_id, gorev_adi: gorev_adi, net_sure_sn: net_sure_sn }, reqUser?.id);
     }

     // 3. Sipariş toplam üretileni ve durumu güncelle
     if(ie && ie.siparis_id) {
         const sip = await recordManager.getRecord(context.tenantSlug, 'siparisler', ie.siparis_id);
         const sip_yeni_uretilen = (sip.uretilen_miktar || 0) + uretilen;
         let sip_durum = sip.durum;
         if(sip_yeni_uretilen >= sip.uretim_hedef_miktar) sip_durum = 'Tamamlandı';
         await recordManager.updateRecord(context.tenantSlug, 'siparisler', ie.siparis_id, { durum: sip_durum, uretilen_miktar: sip_yeni_uretilen }, reqUser?.id);

         // 4. Stok Güncelle (Mamul artar)
         const urunId = sip.urun_id;
         if(urunId) {
            const u = await recordManager.getRecord(context.tenantSlug, 'stok_kartlari', urunId);
            await recordManager.updateRecord(context.tenantSlug, 'stok_kartlari', urunId, { mevcut_stok: (u.mevcut_stok || 0) + uretilen }, reqUser?.id);
         }
     }

     if(typeof publishWS !== 'undefined') publishWS(context.tenantSlug, 'siparis_guncellendi', { action: 'islem_bitir' });
     return { respond: true, status: 200, body: { success: true } };
  }

  if (action === 'fason_kabul') {
     const { takip_no, tartilan_agirlik } = data;

     // Doğrudan SQL ile fason arayalım (recordManager'da custom query desteklenmiyor kolayca)
     const entFason = await sql`SELECT id FROM entities WHERE slug = 'fason_is_emirleri'`;
     const fasonData = await sql`SELECT r.id, 
       MAX(CASE WHEN rf.key = 'takip_no' THEN rf.val_str END) as takip_no,
       MAX(CASE WHEN rf.key = 'urun_id' THEN rf.val_num END) as urun_id,
       MAX(CASE WHEN rf.key = 'kalan_miktar' THEN rf.val_num END) as kalan_miktar
       FROM records r LEFT JOIN record_fields rf ON r.id = rf.record_id 
       WHERE r.entity_id = ${entFason[0].id} GROUP BY r.id HAVING MAX(CASE WHEN rf.key = 'takip_no' THEN rf.val_str END) = ${takip_no}`;

     if(fasonData.length === 0) throw new Error("Fason kaydı bulunamadı!");
     const f = fasonData[0];

     const s = await recordManager.getRecord(context.tenantSlug, 'stok_kartlari', f.urun_id);
     if(!s) throw new Error("Stok kartı bulunamadı!");

     const adet = Math.floor(tartilan_agirlik / (s.birim_agirlik || 1));
     const yeni_kalan = (f.kalan_miktar || 0) - adet;

     await recordManager.updateRecord(context.tenantSlug, 'fason_is_emirleri', f.id, { kalan_miktar: yeni_kalan }, reqUser?.id);
     await recordManager.updateRecord(context.tenantSlug, 'stok_kartlari', s.id, { mevcut_stok: (s.mevcut_stok || 0) + adet }, reqUser?.id);

     return { respond: true, status: 200, body: { success: true, adet, urun_kodu: s.urun_kodu } };
  }

  return { respond: true, status: 400, body: { error: 'Unknown action' } };
} catch (e) {
  return { respond: true, status: 500, body: { error: e.message } };
}

