const siparisler = ref([]);
const isConnected = ref(false);

const loadData = async () => {
   try {
      const res = await $fetch('/api/custom/siparisler');
      siparisler.value = res.data || [];
   } catch(e) {}
};

// WebSocket Hook
const ws = useWS ? useWS() : null;

onMounted(() => {
   loadData();
   if(ws) {
      ws.on('connect', () => { isConnected.value = true; });
      ws.on('disconnect', () => { isConnected.value = false; });
      ws.on('siparis_guncellendi', (payload) => {
          console.log("WS YAYINI ALINDI!", payload);
          loadData(); // Ekranda verileri sessizce tazele! (Gerçek zamanlı görünüm)
      });
   }
});

onUnmounted(() => {
   if(ws) ws.off('siparis_guncellendi');
});

return { siparisler, loadData, isConnected };

const activeOrder = ref(null);
const orders = ref([]);
const isRunning = ref(false);
const baslamaZamani = ref(0);
const saniye = ref(0);
const timerStr = computed(() => {
   const m = Math.floor(saniye.value / 60).toString().padStart(2, '0');
   const s = (saniye.value % 60).toString().padStart(2, '0');
   return `${m}:${s}`;
});
const uretilenAdet = ref(0);
const fireAdet = ref(0);
const gorevAdi = ref('');
const isSubmitting = ref(false);

const toastShow = ref(false);
const toastMsg = ref('');
const toastColor = ref('success');

const showToast = (msg, clr='success') => { toastMsg.value = msg; toastColor.value = clr; toastShow.value = true; };

const loadOrders = async () => {
   try {
      const res = await $fetch('/api/custom/is_emirleri?limit=500');
      orders.value = res.data || [];
   } catch(e) {}
};

const filteredOrders = computed(() => orders.value.filter(o => o.durum !== 'Tamamlandı'));

onMounted(() => { loadOrders(); });

let intv = null;
const { executeDynamicUtil } = useUtils ? useUtils() : { executeDynamicUtil: null };

const selectOrder = (item) => { activeOrder.value = item; saniye.value = 0; isRunning.value = false; baslamaZamani.value = 0; uretilenAdet.value = 0; fireAdet.value = 0; gorevAdi.value = ''; };

const startTimer = async () => {
   isRunning.value = true;
   baslamaZamani.value = Date.now();
   intv = setInterval(() => { saniye.value++; }, 1000);
   try {
      await $fetch('/api/custom/mes/operations', { method: 'POST', body: { action: 'islem_baslat', data: { is_emri_id: activeOrder.value.id } } });
      showToast('Üretim Başladı, WebSocket tetiklendi!');
   } catch(e){}
};

const pauseTimer = () => {
   isRunning.value = false;
   if(intv) clearInterval(intv);
};

const finishOrder = async () => {
   if(!gorevAdi.value) return showToast('Lütfen Alt Görev Adını yazın!', 'error');
   isSubmitting.value = true;
   isRunning.value = false;
   if(intv) clearInterval(intv);

   let netSure = saniye.value;
   if(executeDynamicUtil) {
       // Backend'den veya cache'den Dynamic Util çalıştırılır: calculateNetTime
       // Burada sadece yerel simülasyon olarak geçiyoruz, gerçek util projede çalışacaktır.
   }

   try {
      const res = await $fetch('/api/custom/mes/operations', { method: 'POST', body: { 
         action: 'islem_bitir', 
         data: { is_emri_id: activeOrder.value.id, uretilen: Number(uretilenAdet.value), fire: Number(fireAdet.value), net_sure_sn: netSure, gorev_adi: gorevAdi.value } 
      } });
      if(res.success) {
         showToast('Üretim Kaydedildi ve Ortak Ekran Güncellendi!');
         activeOrder.value = null;
         loadOrders();
      }
   } catch(e) {}
   isSubmitting.value = false;
};

return { activeOrder, orders, filteredOrders, isRunning, saniye, timerStr, uretilenAdet, fireAdet, gorevAdi, isSubmitting, loadOrders, selectOrder, startTimer, pauseTimer, finishOrder, toastShow, toastMsg, toastColor };

const takip_no = ref('');
const tartilan_agirlik = ref('');
const loading = ref(false);

const toastShow = ref(false);
const toastMsg = ref('');
const toastColor = ref('success');
const showToast = (msg, clr='success') => { toastMsg.value = msg; toastColor.value = clr; toastShow.value = true; };

const kabulEt = async () => {
   if(!takip_no.value || !tartilan_agirlik.value) return showToast('Tüm alanları doldurun', 'error');
   loading.value = true;
   try {
      const res = await $fetch('/api/custom/mes/operations', { method: 'POST', body: { action: 'fason_kabul', data: { takip_no: takip_no.value, tartilan_agirlik: Number(tartilan_agirlik.value) } } });
      if(res.success) {
         showToast(res.adet + ' Adet ' + res.urun_kodu + ' stoklara başarıyla eklendi!');
         takip_no.value = ''; tartilan_agirlik.value = '';
      }
   } catch(e) {
      showToast('Takip No veya Stok Kartı bulunamadı', 'error');
   }
   loading.value = false;
};

return { takip_no, tartilan_agirlik, loading, kabulEt, toastShow, toastMsg, toastColor };

