function calculateNetTime(startMs, endMs) {
    // startMs ve endMs milisaniye cinsindendir.
    // Varsayım: 12:00-13:00 arası 1 saat yemek molasıdır. Eğer bu aralığa denk geliyorsa süreden düşülür.
    let totalSec = Math.floor((endMs - startMs) / 1000);
    // Basit bir simülasyon için:
    const dStart = new Date(startMs);
    const dEnd = new Date(endMs);
    if(dStart.getHours() <= 12 && dEnd.getHours() >= 13) {
        totalSec -= 3600; // 1 saat düş
    }
    return totalSec > 0 ? totalSec : 0;
}

